#[test]
fn newton_millimeters() {
    for v in [1.0, 0.3, -42.75, 1e6, 123456.789] {
        // Generated conversion vs. the upstream formula, verbatim.
        let x: f64 = v;
        let base = x * 0.001;
        assert_close(Torque::from_newton_millimeters(v).as_base(), base, F64_TOL);
        let x: f64 = base;
        let back = x * 1000.0;
        assert_close(
            Torque::from_base(base).as_newton_millimeters(),
            back,
            F64_TOL,
        );
        assert_close(
            Torque::from_newton_millimeters(v).as_newton_millimeters(),
            v,
            ROUND_TRIP_TOL,
        );
        // f32 storage.
        assert_close(
            Torque::from_newton_millimeters(v as f32).as_base() as f64,
            base,
            F32_TOL,
        );
        assert_close(
            Torque::from_base(base as f32).as_newton_millimeters() as f64,
            back,
            F32_TOL,
        );
    }
}

